@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h3 class="mb-3">Kanban Board</h3>

@if (isLoading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading...</span>
        </div>
    </div>
}
else if (errorMessage is not null)
{
    <div class="alert alert-danger" role="alert">
        <strong>Error:</strong> @errorMessage
        <button class="btn btn-outline-danger btn-sm ms-2" @onclick="LoadTasks">Retry</button>
    </div>
}
else
{
    <BoardSummaryBar Tasks="tasks" />

    <div class="mb-3">
        <input type="text" class="form-control" placeholder="Search tasks by title..."
               @bind="searchText" @bind:event="oninput" />
    </div>

    <div class="row g-3">
        @{ var columns = new[] { "To Do", "In Progress", "Done" }; }
        @for (var i = 0; i < columns.Length; i++)
        {
            var colName = columns[i];
            var isFirst = i == 0;
            var isLast = i == columns.Length - 1;

            <KanbanColumn ColumnName="@colName"
                          Tasks="GetFilteredTasks(colName)"
                          IsFirst="isFirst"
                          IsLast="isLast"
                          OnMoveTask="e => HandleMoveTask(colName, e.TaskId, e.Direction)"
                          OnAddTask="e => HandleAddTask(colName, e.Title, e.Assignee, e.Priority, e.DueDate)" />
        }
    </div>
}

@code {
    private List<TaskItem> tasks = new();
    private string searchText = "";
    private bool isLoading = true;
    private string? errorMessage;

    private static readonly string[] ColumnOrder = ["To Do", "In Progress", "Done"];

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var filtered = tasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            filtered = filtered.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return filtered.ToList();
    }

    private async Task HandleMoveTask(string currentColumn, int taskId, KanbanColumn.MoveDirection direction)
    {
        var currentIndex = Array.IndexOf(ColumnOrder, currentColumn);
        var newIndex = direction == KanbanColumn.MoveDirection.Left ? currentIndex - 1 : currentIndex + 1;

        if (newIndex < 0 || newIndex >= ColumnOrder.Length) return;

        var newStatus = ColumnOrder[newIndex];

        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var taskIndex = tasks.FindIndex(t => t.Id == taskId);
            if (taskIndex >= 0)
            {
                var old = tasks[taskIndex];
                tasks[taskIndex] = old with { Status = newStatus };
            }
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }

    private async Task HandleAddTask(string column, string title, string assignee, string priority, DateTime dueDate)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(title, assignee, priority, dueDate);
            tasks.Add(newTask);
        }
        catch (Exception ex)
        {
            errorMessage = ex.Message;
        }
    }
}

